     1	"use client";
     2	
     3	import { useEffect, useState } from "react";
     4	import { UnicornScene } from "unicornstudio-react";
     5	
     6	function CubeFallback() {
     7	  return (
     8	    <div className="cube-fallback" aria-hidden="true">
     9	      <span />
    10	      <span />
    11	      <span />
    12	    </div>
    13	  );
    14	}
    15	
    16	export function CubeUnicorn() {
    17	  const [canRender, setCanRender] = useState(false);
    18	
    19	  useEffect(() => {
    20	    const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
    21	    const update = () => {
    22	      const canvas = document.createElement("canvas");
    23	      const hasWebGL = Boolean(
    24	        canvas.getContext("webgl2") || canvas.getContext("webgl"),
    25	      );
    26	      setCanRender(hasWebGL && !reducedMotion.matches);
    27	    };
    28	
    29	    update();
    30	    reducedMotion.addEventListener("change", update);
    31	    return () => reducedMotion.removeEventListener("change", update);
    32	  }, []);
    33	
    34	  return (
    35	    <div
    36	      className="cube-stage"
    37	      role="img"
    38	      aria-label="Interactive three-dimensional cube"
    39	    >
    40	      {canRender ? (
    41	        <UnicornScene
    42	          jsonFilePath="/unicorn/cube-unicorn.json"
    43	          sdkUrl="https://cdn.jsdelivr.net/gh/hiunicornstudio/unicornstudio.js@v2.2.5/dist/unicornStudio.umd.js"
    44	          width="100%"
    45	          height="100%"
    46	          lazyLoad
    47	          ariaLabel="Interactive three-dimensional cube"
    48	          placeholder={<CubeFallback />}
    49	          showPlaceholderOnError
    50	          showPlaceholderWhileLoading
    51	          onError={() => setCanRender(false)}
    52	        />
    53	      ) : (
    54	        <CubeFallback />
    55	      )}
    56	    </div>
    57	  );
    58	}

