--- cube ---
     1	"use client";
     2	
     3	import { useEffect, useState } from "react";
     4	import { UnicornScene } from "unicornstudio-react";
     5	
     6	function CubeFallback() {
     7	  return (
     8	    <div className="cube-fallback" aria-hidden="true">
     9	      <span />
    10	      <span />
    11	      <span />
    12	    </div>
    13	  );
    14	}
    15	
    16	export function CubeUnicorn() {
    17	  const [canRender, setCanRender] = useState(false);
    18	
    19	  useEffect(() => {
    20	    const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)");
    21	    const update = () => {
    22	      const canvas = document.createElement("canvas");
    23	      const hasWebGL = Boolean(
    24	        canvas.getContext("webgl2") || canvas.getContext("webgl"),
    25	      );
    26	      setCanRender(hasWebGL && !reducedMotion.matches);
    27	    };
    28	
    29	    update();
    30	    reducedMotion.addEventListener("change", update);
    31	    return () => reducedMotion.removeEventListener("change", update);
    32	  }, []);
    33	
    34	  return (
    35	    <div
    36	      className="cube-stage"
    37	      role="img"
    38	      aria-label="Interactive three-dimensional cube"
    39	    >
    40	      {canRender ? (
    41	        <UnicornScene
    42	          jsonFilePath="/unicorn/cube-unicorn.json"
    43	          sdkUrl="https://cdn.jsdelivr.net/gh/hiunicornstudio/unicornstudio.js@v2.2.5/dist/unicornStudio.umd.js"
    44	          width="100%"
    45	          height="100%"
    46	          lazyLoad
    47	          ariaLabel="Interactive three-dimensional cube"
    48	          placeholder={<CubeFallback />}
    49	          showPlaceholderOnError
    50	          showPlaceholderWhileLoading
    51	          onError={() => setCanRender(false)}
    52	        />
    53	      ) : (
    54	        <CubeFallback />
    55	      )}
    56	    </div>
    57	  );
    58	}

--- motion ---
     1	"use client";
     2	
     3	import { useRef } from "react";
     4	import { useGSAP } from "@gsap/react";
     5	import gsap from "gsap";
     6	import { ScrollTrigger } from "gsap/ScrollTrigger";
     7	
     8	gsap.registerPlugin(useGSAP, ScrollTrigger);
     9	
    10	export function MotionRoot({ children }: { children: React.ReactNode }) {
    11	  const scope = useRef<HTMLDivElement>(null);
    12	
    13	  useGSAP(
    14	    () => {
    15	      if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) return;
    16	
    17	      gsap.utils
    18	        .toArray<HTMLElement>("[data-project-media]")
    19	        .forEach((media) => {
    20	          gsap.fromTo(
    21	            media,
    22	            { scale: 0.8, opacity: 0.2 },
    23	            {
    24	              scale: 1,
    25	              opacity: 1,
    26	              ease: "none",
    27	              scrollTrigger: {
    28	                trigger: media,
    29	                start: "top 90%",
    30	                end: "center 55%",
    31	                scrub: true,
    32	              },
    33	            },
    34	          );
    35	        });
    36	
    37	      gsap.utils
    38	        .toArray<HTMLElement>("[data-stack-card]")
    39	        .forEach((card, index) => {
    40	          ScrollTrigger.create({
    41	            trigger: card,
    42	            start: `top ${96 + index * 18}px`,
    43	            endTrigger: "[data-stack]",
    44	            end: "bottom bottom",
    45	            pin: true,
    46	            pinSpacing: false,
    47	          });
    48	        });
    49	    },
    50	    { scope },
    51	  );
    52	
    53	  return <div ref={scope}>{children}</div>;
    54	}

